                // mode (GameModes) whose entry point waits for these 20 frames and then runs the same check
                // (AppModes.cs); the menu check of --smoke-test and --menu-smoke-test is checkMainMenu (MenuSmoke.cs).
                menuSmokeFrames += 1;
