    public void updateCamera(bool snap, double dt = 1.0 / 60)
    {
        if (isDirtTrack) { raceHUD.mapRegion = RaceMapRegion.at(new Double2(simulation.x, simulation.z), previous: raceHUD.mapRegion); }
