        {
            if (i == index) continue;
            var other = new Double2(states[i].x, states[i].z) - p;
            if (Simd.length(other) < 1.35 && Simd.dot(other, direction) > 0.15 && abs(other.x * direction.y - other.y * direction.x) < 0.65)
