            trackedTotal++;
            if (trackedNodes.Count < trackedPruneAt) return;
            trackedNodes.RemoveAll(h => { if (h.Target is Node n && IsInstanceValid(n)) return false; h.Free(); return true; });
            trackedPruneAt = Math.Max(4096, trackedNodes.Count * 2);
