+import AppKit
+
+private final class LoadingProgressBar:NSView {
+    var value=0.0 { didSet { needsDisplay=true;setAccessibilityValue(value) } }
+    override func draw(_ dirtyRect:NSRect) {
+        NSColor(calibratedWhite:0.22,alpha:1).setFill()
