                double dx = st * Math.Sin(phi), dy = ct, dz = -st * Math.Cos(phi);
                var c = img.GetPixel(x, y);
                double r = NSColor.SrgbToLinear(c.R), g = NSColor.SrgbToLinear(c.G), b = NSColor.SrgbToLinear(c.B);
