        ShaderNames.SetGlobal(ShaderNames.Of("scn_fog_range"), new Vector4((float)scene.fogStartDistance, (float)scene.fogEndDistance, (float)Math.Max(1e-3, scene.fogDensityExponent), fogOn ? 1 : 0));
