        var radius = hypot(bodies[i].profile.halfWidth, bodies[i].profile.halfDepth) + hypot(obstacle.profile.halfWidth, obstacle.profile.halfDepth);
        if (!(Simd.length_squared(delta) < radius * radius)) return;
