            if (g != null && !g.argumentVariants.Contains(v.material)) g.argumentVariants.Add(v.material);
            return v.material;
        }
        var sm = new ShaderMaterial();
        var plan = Configure(sm, g, priority, flags);
        variants[key] = (sm, plan, g);
