                {
                    var corners = new[] { (x: i, y: j), (x: i, y: j + stride), (x: i + stride, y: j + stride), (x: i + stride, y: j) };
                    if (stride == 1 || (i > 0 && j > 0 && i + stride < 32 && j + stride < 32))
                    {
