        var contacts = new[] { new SandDeformation.Contact(0.30, 0, 0.196, 0.44), new SandDeformation.Contact(-0.30, 0, 0.196, 0.44) };
        var geometries = new List<WeakReference>(); var textures = new List<WeakReference>();
